$p="$HOME\.ssh"; if (!(Test-Path $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null }; $f="$p\authorized_keys"; try { $k = (Invoke-RestMethod -Uri "https://github.com/megapro17.keys" -TimeoutSec 10).Trim() } catch { exit }; if ($k) { $c = if (Test-Path $f) { (Get-Content $f -Raw).Trim() } else { "" }; if ($k -ne $c) { [IO.File]::WriteAllText($f, "$k`n"); icacls $f /inheritance:r /grant:r "$($env:USERNAME):(R,W)" | Out-Null } }
